// Extraer el número de teléfono, la imagen (URL o Base64) y el empleado deseado
const body = $input.first().json.body || $input.first().json;

// Soporta payloads de Evolution API, Meta Cloud API o Twilio
const imageUrl = body.mediaUrl || body.imageUrl || body.data?.message?.imageMessage?.url || body.entry?.[0]?.changes?.[0]?.value?.messages?.[0]?.image?.id || "";
const rawBase64 = body.base64 || body.data?.base64 || "";
const senderPhone = body.phone || body.from || body.entry?.[0]?.changes?.[0]?.value?.contacts?.[0]?.wa_id || "";
const caption = body.caption || body.message || body.text || "";

// Empleado por defecto: SCHUSTER ADRIAN
let targetEmployee = "SCHUSTER ADRIAN";
if (caption.trim().length > 3 && !caption.toLowerCase().includes("http")) {
  targetEmployee = caption.trim().toUpperCase();
}

return [{
  json: {
    imageUrl,
    rawBase64,
    senderPhone,
    targetEmployee,
    timestamp: new Date().toISOString()
  }
}];

