// Normalizar respuesta de Gemini o OpenAI
const geminiText = $input.first().json.candidates?.[0]?.content?.parts?.[0]?.text;
const openAiText = $input.first().json.choices?.[0]?.message?.content;
const rawJsonText = geminiText || openAiText || "{}";

// Limpiar posibles bloques ```json
const cleanJson = rawJsonText.replace(/```json/g, '').replace(/```/g, '').trim();
const parsed = JSON.parse(cleanJson);

const employeeName = parsed.empleado || $('Extract & Filter Employee').first().json.targetEmployee || "SCHUSTER ADRIAN";
const legajo = parsed.legajo || "208376";
const semana = parsed.semana || [];

// Normalizar días
const normalizedDays = semana.map(item => {
  let startTime = null;
  let endTime = null;

  if (!item.franco && item.horario && item.horario.toLowerCase() !== 'libre') {
    const matches = item.horario.match(/(\d{1,2}:\d{2})/g);
    if (matches && matches.length >= 2) {
      startTime = matches[0];
      endTime = matches[1];
    }
  }

  return {
    date: item.fecha,
    dayName: item.dia_semana,
    timeRange: item.horario || (item.franco ? 'LIBRE' : '10:00 A 18:00'),
    startTime: startTime,
    endTime: endTime,
    isDayOff: Boolean(item.franco || item.horario?.toUpperCase() === 'LIBRE'),
    notes: null,
    source: 'OCR_WHATSAPP'
  };
});

return [{
  json: {
    employeeName,
    legajo,
    days: normalizedDays,
    senderPhone: $('Extract & Filter Employee').first().json.senderPhone
  }
}];
